add('GR4-M02-003','CONFIRM_WITH_REFINEMENT','P3',['util','ruby','interpreter'],['wp06','wp34','tests_kernel'],['M02-random','M02-callers-overrides'],['WP06 §5.1–5.3与TM05–07','WP34无放回继承、拼图/雷板洗牌、设施重复采样、战斗记录/平局洗牌的实质命中均为其它规则'], '全131未找到有跨次记忆的1/7重复门。源码只有定义、无默认静态消费者/覆写；可实例化并调用get，不能称默认全局随机服务。',{'minimal':'n=2，首次0后，本轮已见={0}、未见={1}。后一次P(0)=1/7、P(1)=6/7；无放回下一次P(0)=0，独立均匀随机P(0)=1/2。','rejected_claim':'单看输出0,0可以区分无放回，却不能排除普通均匀随机；原finding的这一“也不同”须用条件分布或明确随机输入协议证明。','normal':'重复门未命中从未见者均匀取；重复门命中不移除未见者。','boundary':'全集出现完毕后，下次先重开轮次且首抽不走重复门；n=1恒0；不能承诺每n次全集覆盖。'},static('M02'),newhist,'原R中轮次记忆、重复分支与重置构成确实独立的可调用能力，B普通随机/洗牌标题并未承接它；P3合理。确认遗漏，但拒绝用一个允许重复的序列证明与无记忆均匀抽样不同。',['用上列条件概率对照替换不足以区分均匀随机的单序列断言；这是静态数学推导，不是统计测试。','保留正整数n范围、无默认消费者、无跨语言随机序列一致性承诺。'],['非法规模、真实作者/插件使用、原生随机实现与跨语言序列未证。'])
add('GR4-M03-001','CONFIRM_WITH_REFINEMENT','P2',['char','event','ruby'],['wp12','wp13','routes','wp75','tests_world'],['M03-range','M03-definitions'],['WP12 §4.3已给普通随机不预转向/成功后转向','路线§1/45、MR08/10–22、WP75 §8.6均只给脚本文本调度；不是范围候选算法'], '候选过滤/原始锚点/单轴能力未承接；阻挡时不预转向和通用移动应引用现有合同，不另计缺失。',{'minimal':'事件初始锚点(5,5)，当前(7,5)，r=2/s=0，普通地面均可通行：候选仅左，尝试到(6,5)。重定锚点或四向抽样会允许其它方向。','normal':'当前位置等于锚点且r=2/s=0，左右各半；原始锚点来自事件数据，moveto不重定它。','boundary':'r=s=0无抽样/无尝试；负轴界给该轴两向；右界左阻挡时只尝试左，不重新选其它方向，不转身。','math':'r>0：左当x>x0−r，右当x<x0+r；s>0：下当y<y0+s，上当y>y0−s。筛选候选序左→右→下→上；非空仅一次均匀索引选择。'},static('M03'),newhist,'ROOT候选序及严格比较经原函数独立核对正确。源选向后调用普通不预转向移动，受阻不重抽；原始锚点独立于当前位置。既有路线前缀只决定让出，不足以决定范围边界。',['补一般比较式、负/零/正三态、UD/LR禁用另一轴；说明是方向过滤而非越界自动钳回。','候选序只用于固定参考抽样索引解释，不要求未来保留源容器结构或跨语言随机序列。','将不预转向/成功转向引用WP12既有规则，不新增重复根因；WP75的正确调度无需重写。'],['默认Demo调用未证；源路线45可调用不等于真实NPC素材/事件链已运行；任意非整数/非法范围未穷尽。'])
add('GR4-M03-002','CONFIRM_WITH_REFINEMENT','P2',['field','char','player','scene','surf','interpreter','commands','temp','world','mapfactory'],['wp59','wp12','wp11','wp61','wp16','tests_world','tests_render'],['M03-surf','M03-definitions','CA-shared-alias-supplement','CA-boundary-supplement'],['WP59 §7转移重置保证','WP12 §5.2/ WP61 §3.2只保证玩家步后通知清理','WP11同图转移、MP20/21与WP16 §4.3/B04-W07分别是车辆标记与显示消费，不提供临时坐标清理'], '固定源字段写点没有转移独立清理；已有正确步后/显示合同不能使WP59的无条件转移重置句成立。',{'minimal':'合法同图20×20；静止玩家(5,5)向右、through=false、非调试Ctrl穿透、无强制移动/冰瀑、ending_surf=false。脚本直接启动上水，具名非through事件占(6,5)，前跳拒绝且不设运动计时；随后同图201保游泳到(10,10)，期间无玩家步后通知或其它改写。转移正常返回仍保留旧基点(6,5)。','normal':'成功跳跃完成并满足地图场景/玩家/存在基点三门时才清基点。','boundary':'取消游泳参数true仅清冲浪/潜水标记，未独立清这两个临时字段；后继合格步通知仍可能清理，不声称永久残留。','reachability':'直接脚本工具+201可达，不能冒充默认Demo；人为ending_surf=true会先挡解释器，不能用正常201证明该人工状态可越过等待。'},static('M03'),{'relation':'producer_cleanup_vs_existing_display_consumer','ids':['GIR-FD82-C064'],'assessment':'已读旧qualified_scope及B WP16/B04-W07。C064的基点已清稳定冲浪/visible与opacity是显示消费者；新项质疑临时量何时清，不改旧显示合同，关系准确。'},'源码追至玩家jump覆写、普通更新、转移moveto、显示重建与步后通知，失败跳跃没有进入update_move，转移也不单独生成清理通知。WP59多给了一项保证；报告需保持有界条件与观察点，不能推广成默认软锁。',['将玩家through=false、无调试Ctrl穿透、ending_surf=false及未启动运动计时写成反例前提。','区分正常201保游泳、直接默认转移取消游泳及步后通知清理；保留显示输入与真实像素未证的区别。','人工ending_surf=true仅作直接转移/等待门的条件事实，不能称正常201可穿过该等待门。'],['完整宿主像素、真实Demo上水/转移链、外部脚本改写和所有转移组合未运行。'])
add('GR4-M03-003','CONFIRM_WITH_REFINEMENT','P2',['commands','interpreter','event','metadata'],['commands','wp13','wp11','wp09','tests_world'],['M03-erase','M03-definitions'],['WP13 §4.1和矩阵§2已有false本轮停止规则','矩阵116缺其具体返回/推进；WP13 §3.3及GR3-MR12只确定辅助与普通实例两者区别','WP11/09恢复端不提供116登记门'], '不能把已有通用停止/推进说成全局缺失；缺的是116与这条规则的绑定，以及正ID而非实例存在的登记门。',{'minimal':'主解释器绑定图B（与当前B相同）、ID7、无等待/子解释器等阻塞，列表116→可见全局开关命令→终止项，局部记录有效为空。即使B缺事件7，执行116仍登记(B,7)=真，索引前进1并本次不执行后条。','normal':'B/7存在时先消去刷新再登记；直接实例消去不登记；记录式辅助存在实例才登记。','boundary':'ID0不登记但仍推进停止；局部记录对象空值时安全跳过登记；若解释器地图失联，前置门把ID清0，不能沿用正ID例。','timing':'后条等下一次合格解释器调用，不等于保证下一显示帧必执行。'},static('M03'),{'relation':'new_scope_same_root','ids':['GR3-M03-004'],'assessment':'B当前已标该历史条款并承接辅助/恢复部分；本项补主分派116生产端。保留旧关闭身份，不宣称旧全项重验，不与它简单MERGE而丢失新入口缺口。'},'116的真实分派、实例安全消去和记录函数分别核实；当前正式三入口对照无法唯一推出其结果。通用false停止规则存在但116行没有给出它返回false及命令体自推进，所以仍需有界修正。',['明确解释器地图=当前图、无等待门及116不在终止项位置的夹具。','以通用推进合同已有为前提，只补116具体控制结果，不重复报通用算法缺失。','三入口分别列门；保持旧恢复清表合同与历史关闭状态。'],['真实Demo安排、并行解释器销毁后的继续、宿主更新时机未运行；本例限定主解释器。'])
add('GR4-M04-001','CONFIRM_WITH_REFINEMENT','P2',['speciesfiles','pokemon','forms','sprites','summary','pbsforms','hatch','time'],['wp18','wp19','wp21','wp15','wp35','tests_forms','tests_eggs'],['M04-form','M04-form-overrides','CA-shared-alias-supplement'],['WP18 §3.4明确把图像归简化读取','WP21 §3.2-R03已保留读取副作用、FM07/08已给限时回退','强反证：WP35 §5.2/§9和EG-13/20已有孵化资源动态读写的明确合同'], '不能声称正式集完全没有图像动态读取副作用；WP35已有具体承接。它与WP18泛称形成矛盾，仍不能让按个体正背精灵/图标的入口归属无歧义。',{'minimal':'合法非蛋FURFROU存储形态1、整数时间戳t、无forced、非战斗/非仓库，当前t+432001；直接按个体取正面图到达形态求值：资源解析前存储形态0、时间戳空并走完整提交。按WP18简化读则仍1/t。','normal':'恰t+432000不回退。','boundary':'战斗/仓库守卫保留存储值；forced=1不求动态；forced=0返回0但不提交存储1；显式数值形态的低层资源调用只消费输入。','caller_caution':'孵化虽调用显式物种资源入口，调用者先求个体动态形态仍有副作用；不能由低层接口纯消费反推上游调用链纯读。'},static('M04'),{'relation':'adjacent_dynamic_form_consumer_with_existing_shared_contract','ids':['GIR-FD82-A053','GR3-M04-001'],'assessment':'已读A053限定scope、孵化源链和B EG-13/20。A053是孵化核心与演出查询分层；M04是通用按个体取图/摘要入口及WP18上游分类。二者共享动态查询机制但不同消费范围，邻接关系准确；不重开A053，也不混SPINDA像素旧项。'},'原R正背精灵/图标入口读取普通形态，形态提交链与FURFROU严格超5天条件均有明确源证。WP35是必须承认的已覆盖部分，但不能消除WP18直接相反的泛称；整改应收窄为入口归属/跨文档一致性，不重建整个动态形态规格。',['将WP35 §5.2/§9和EG-13/20作为已承接的强反证加入结论。','最低整改是纠正WP18图像泛称，并明确个体入口继承动态读取合同；复用WP21/35既有提交/守卫，不重复扩成全域必修。','显式物种/形态对照须提供已求值的数值参数；上游可能先读取个体，不能笼统称所有物种入口调用链无副作用。'],['实际资源和宿主像素未证；图鉴/能力重算只按依赖正常的静态调用链判定，插件改写未证。'])
add('GR4-M05-001','CONFIRM','P2',['battleitems','itemeffects','itemutils','pokemon','commandphase','choosecommands','actionitem','shadow','itemdata','party','pbsitems','pbsmoves'],['wp28','wp20','wp40','wp67a','wp51','wp50','wp50table','tests_items','tests_ai'],['M05-pp','M05-pp-overrides','CA-shared-alias-supplement'],['WP28 §3.2/§3.5/§5.2；IU-07/26–28','WP20恢复辅助、WP40通用资格、WP67-A非蛋目标/拒绝循环','WP51 I06/I07缺索引与WP50持有LEPPA不是人工带有效索引主动恢复'], '已有通用资格/非蛋条件没有战斗PP族HP>0门。AI“存活”前提只是异常例限制，不能反推出场外或战斗全部资格；附表评级/投掷也不承接此门。',{'minimal':'内部战斗有可行动A、普通非蛋非Hyper后备B；B HP0/100、唯一TACKLE PP0/35、ETHER库存1，带有效索引确认。战斗资格拒绝，库存1/PP0/HP0保持；独立场外同初态恢复PP10、库存0、HP0。','normal':'只把B HP改1且PP缺口仍在，两处均可恢复；战斗需后续复检仍通过。','boundary':'满PP或取消不消费；MAX两种回满35、ETHER/LEPPA/ELIXIR在单招例恢复10；非蛋存活不是所有战斗道具统一规则，复活例另有资格。','reachability':'默认物品用途允许选非蛋后备，实际队伍选择器不滤HP0；普通前置/Shadow覆写不替代也不撤销PP家族门。'},static('M05'),newhist,'默认数据与真实人工菜单→通用资格→PP家族→登记扣减链均独立检查。场外通用门不拒濒死、恢复辅助不改HP。反例比较同一有效成员和招式，能排除错误地统一两上下文资格的实现；P2合理。',[],['宿主菜单/消息演出未运行；第三方覆盖与全部数据变体不在本项。'])
add('GR4-M06-001','CONFIRM','P3',['daycare','pokemon','pbsitems','gamedata','itemdata'],['wp34','wp20','tests_forms','wp50','tests_ai'],['M06-power','M06-iv-overrides'],['WP34 §7数量规则正确；BR16/17/19与BR18对照','WP20单一持物及同一身份比较','力量EV/速度、红线迷恋/拾取、AI评级附表均不提供第三持物或额外继承数量'], 'BR18的5−2分支没有满足羁绊之绳门的普通输入；正确正文不能让错误验收分支成立。不是整个遗传算法缺失。',{'minimal':'母持POWERWEIGHT、父持POWERBRACER，普通单持物。蛋初六IV均1；母HP31、父ATTACK31，其余亲本IV均0。只继承HP31/ATTACK31和另1项0，余3项保1。错误5−2预期会另写3项0。','normal':'无Knot时总继承3；双同力量只固定一项，余2项随机。','boundary':'合法5项对照需世代≥6且一方Knot/另一方至多一件Power：固定1+其余4；旧代同组合固定1+其余2。','distinguishes':'初始值1与亲本被继承值0/31分开，避免把随机初值偶合误当实际继承数量。'},static('M06'),newhist,'源数量门要求Knot，两个普通持物槽已被不同Power占满且三身份确实不同；B正文正确而BR18接受不可能分支。最小反例条件可满足，P3局部测试纠错合适。',[],['第三方多持物/重写比较可改变前提，但无该材料且不属于普通BR18输入；未运行繁育。'])

